{
  "title": "A Lighter, Cheaper Ubud Day",
  "summary": "We slow the pace around Ubud, keeping the rice terraces and swapping pricey stops for free palace and ridge time, with a vegan lunch and a special dinner to close the day.",
  "stops": [
    {
      "poi_id": "p3",
      "kind": "activity",
      "must_do_id": "m2",
      "note": "The must-do rice terraces stay, and the morning light makes them glow for the photo lovers.",
      "must_do_id": "m2"
    },
    {
      "poi_id": "p16",
      "kind": "meal",
      "must_do_id": null,
      "note": "Lunch at Alchemy keeps everyone happy with vegan plates, and it is easier on the wallet than the old plan.",
      "must_do_id": null
    },
    {
      "poi_id": "p6",
      "kind": "activity",
      "must_do_id": null,
      "note": "Ubud Palace is free and full of history, a calm swap for the pricier monkey forest.",
      "must_do_id": null
    },
    {
      "poi_id": "p7",
      "kind": "activity",
      "must_do_id": null,
      "note": "The ridge walk stays free and open all day, perfect for a slower afternoon breeze.",
      "must_do_id": null
    },
    {
      "poi_id": "p20",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner at Locavore NXT is the one splurge, with vegetarian options for the crew.",
      "must_do_id": null
    }
  ]
}
